-- PROJEXA-BUILD-001 U-22 (Phase 3, WO 3.1 / 3.2 / 3.6, PMD-17): the data half
-- of the evidence standard on platform.sumeet_requirements. Rows only; no
-- schema change. Needs drizzle/0616_build001_requirement_evidence.sql first.
--
-- WHAT
--   (a) INSERT the 31 exceptions-directive rows EXC-ITEM-01..EXC-ITEM-31
--       (ON CONFLICT (id) DO NOTHING). Ids, titles and detectors are
--       ai-os/projexa-build-001/REQUIREMENTS_111_REGISTER.csv; the detectors are
--       the find*() functions of src/lib/services/construction-exceptions-service.ts
--       at commit 6d531f53 (PR #1752), wired into getProjectExceptions().
--       source = 'construction-exceptions-service.ts@6d531f53' (register row BR-307; platform.sumeet_gap is
--       NOT the source, PMD-17). sort_order continues after the highest
--       non-EXC row (83 on 2026-09-25, so 84..114). updated_at takes its
--       default now(); updated_by = 'BUILD-001 U-22'.
--       Set honestly: status 'OPEN - ...' (none is DONE), closure_state 'OPEN',
--       built 'YES' for items 1-28 (the detector exists on main and its
--       verify_command passed on 2026-09-25) and 'n/a' for the META items 29-31,
--       verified_in_db and tested_in_live_ui NULL (never checked against live
--       data or the PROJEXA screen). Each row gets a verify_command (items 1-28:
--       the detector's own tests in construction-exceptions-service.test.ts plus
--       the aggregator test that proves all 28 item numbers are reported; items
--       29-31: a register-level SELECT on platform.sumeet_requirements, BR-310)
--       and, for items 1-28, evidence_ref = the 6d531f53 commit.
--   (b) UPDATE the existing register rows: 69 of the 80 get a
--       verify_command and 72 get an evidence_ref, each only where the
--       column is still NULL (coalesce), so a value written by hand is never
--       overwritten. updated_at and updated_by are NOT touched on these rows,
--       so the down file can restore them exactly. status is never changed.
--       Every value, what was run and its result on 2026-09-25 are in
--       ai-os/projexa-build-001/U22_REQUIREMENT_CHECKS.md.
--
-- CONVENTION: a verify_command runs from the compliance-tracker repo root. A
--   sql-assert command over tenant data or over platform.sumeet_requirements
--   (RLS on, service_role policy only) needs VERIFY_DATABASE_URL for a role
--   that can see the rows; app_runtime reads 0 for the wrong reason (PMD-22).
--
-- NOT SET, ON PURPOSE (listed in U22_REQUIREMENT_CHECKS.md for the PM):
--   verify_command stays NULL where no compliance-tracker-runnable check
--   exercises the requirement (UI-only PROJEXA rows R-15, R-31, R-92; owner
--   decisions and security items R-A1, R-A2, R-A3, R-A5, R-A7; R-B2, R-C17,
--   R-96). evidence_ref stays NULL where no commit, PR or dated query result
--   could be found (R-A1, R-A2, R-A3, R-A7, R-C17, R-93, R-96, R-98).
--
-- HOW IT IS APPLIED: through the Supabase MCP (apply_migration) by the PM,
--   after 0616, after the PGlite proof
--   src/lib/services/sumeet-requirements-evidence-migration.pglite.test.ts
--   passes. Not in PHASE2_MIGRATIONS.txt: a rows-only file leaves the schema
--   hash unchanged, so the schema-hash rehearsal cannot prove it.
--   Idempotent: ON CONFLICT DO NOTHING and coalesce, so a second run changes
--   nothing.
--
-- DATA LOSS: none. New rows only, and only NULL cells of the two new columns
--   are filled.
--
-- ROLLBACK: drizzle/down/0617_build001_requirement_evidence_data.down.sql

BEGIN;

SET LOCAL lock_timeout = '5s';

DO $guard$
BEGIN
  IF (SELECT count(*) FROM information_schema.columns
      WHERE table_schema = 'platform' AND table_name = 'sumeet_requirements'
        AND column_name IN ('verify_command', 'evidence_ref')) <> 2 THEN
    RAISE EXCEPTION '0617 REFUSED: platform.sumeet_requirements has no verify_command / evidence_ref columns. Apply drizzle/0616_build001_requirement_evidence.sql first. Nothing was changed.';
  END IF;
END
$guard$;

-- (a) the 31 exceptions-directive rows ---------------------------------------
INSERT INTO platform.sumeet_requirements
