   route, file_path, github_pr, next_action, updated_by, closure_state, verify_command, evidence_ref)
SELECT v.id,
       base.max_sort + v.n,
       v.area, v.requirement, 'construction-exceptions-service.ts@6d531f53', v.status, v.built, NULL, NULL,
       v.route, v.file_path, v.github_pr, v.next_action, 'BUILD-001 U-22', 'OPEN', v.verify_command, v.evidence_ref
